"""Adversarial plan instances: timing + exact cross-check by independent DFS."""
import json, random, sys, time
sys.path.insert(0,'/workspace/tmp')
from harness import run

def exact(req):
    """Independent exact solver: DFS over all feasible subsets."""
    caps=req['capacities']; flows=req['flows']; warmup=req['warmup']
    offers=req['offers']; pinned=set(req['pinned'])
    ben={}
    for f in flows:
        H=len(f['template'])//2; kinds=f['kinds']; N=len(f['path']); h=N-1
        per=(H-4-kinds.count('D'))*N
        qo=kinds.index('Q'); to=kinds.index('T'); tpl=bytes.fromhex(f['template'])
        tot=0; idx=0
        for r in offers[f['id']]:
            hb=bytes.fromhex(r['header']); cnt=r['count']; end=idx+cnt
            if end>warmup:
                e=end-max(idx,warmup)
                if all(hb[i]==tpl[i] for i,c in enumerate(kinds) if c=='K') and hb[qo]<=7 and hb[to]>h:
                    tot+=per*e
            idx=end
        ben[f['id']]=tot
    ids=[f['id'] for f in flows]
    pinben=sum(ben[p] for p in pinned)
    use0={}
    for f in flows:
        if f['id'] in pinned:
            for n in f['path']: use0[n]=use0.get(n,0)+1
    for n,u in use0.items():
        if u>caps[n]: return {'infeasible':True}, ben
    cands=[i for i,f in enumerate(flows) if f['id'] not in pinned and ben[f['id']]>0]
    paths=[f['path'] for f in flows]
    best=[(-1,0),0]
    used=dict(use0)
    n=len(cands)
    def dfs(i, b, c):
        if i==n:
            if (b,-c)>(best[0][0],-best[0][1]):
                best[0]=(b,-c)
            return
        # exclude
        dfs(i+1,b,c)
        fid=flows[cands[i]]['id']
        p=paths[cands[i]]
        for node in p: used[node]=used.get(node,0)+1
        if all(used[node]<=caps[node] for node in p):
            dfs(i+1, b+ben[fid], c+1)
        for node in p: used[node]-=1
    dfs(0, pinben, len(pinned))
    return {'saved':best[0][0],'count':-best[0][1]}, ben

def mk(seed, style):
    rng=random.Random(seed)
    if style=='clique9':
        nodes=['n%d'%i for i in range(9)]
        caps={n:11 for n in nodes}
        nf=22; mk_path=lambda: rng.sample(nodes,9)
    elif style=='half-tight':
        nodes=['n%d'%i for i in range(10)]
        caps={n:2 for n in nodes}
        nf=22; mk_path=lambda: rng.sample(nodes,9)
    elif style=='pairs':
        nodes=['n%d'%i for i in range(12)]
        caps={n:1 for n in nodes}
        nf=22; mk_path=lambda: rng.sample(nodes,4)
    elif style=='mixed-caps':
        nodes=['n%d'%i for i in range(14)]
        caps={n:rng.choice([1,2,3]) for n in nodes}
        nf=22; mk_path=lambda: rng.sample(nodes,rng.randint(5,9))
    elif style=='bimodal':
        nodes=['n%d'%i for i in range(8)]
        caps={n:rng.choice([1,8]) for n in nodes}
        nf=22; mk_path=lambda: rng.sample(nodes,rng.randint(3,8))
    flows=[]
    for i in range(nf):
        H=rng.choice([8,64,256])
        nd=rng.randint(0,(H-5)//2)
        kinds=['K']*(H-nd-2-len([1]))  # placeholder
        kinds=['K']*(H-nd-2)+['D']*nd+['Z']*0+['Q','T']
        rng.shuffle(kinds)
        flows.append({'id':'f%02d'%i,'path':mk_path(),'template':bytes(rng.randrange(256) for _ in range(H)).hex(),'kinds':''.join(kinds)})
    offers={}
    base={}
    for f in flows:
        H=len(f['template'])//2
        hb=bytearray(H)
        for pos,c in enumerate(f['kinds']):
            if c=='K': hb[pos]=int(f['template'][2*pos:2*pos+2],16)
            elif c=='Q': hb[pos]=3
            elif c=='T': hb[pos]=250
        offers[f['id']]=[{'header':bytes(hb).hex(),'count':1}]
        base[f['id']]=1
    # near-equal benefits to defeat bound pruning: count = rank
    order=list(flows)
    for i,f in enumerate(order):
        offers[f['id']][0]['count'] = 10**6 + (nf-i)*3
    return {'mode':'plan','capacities':caps,'flows':flows,'warmup':0,'pinned':[],'offers':offers}

for style in ['clique9','half-tight','pairs','mixed-caps','bimodal']:
    for seed in range(3):
        req=mk(seed,style)
        t=time.time(); out=run([req]); dt=time.time()-t
        ref,ben = exact(req)
        g=out[0]
        if 'infeasible' in ref:
            ok = (g=={'infeasible':True})
        else:
            ok = ('selected' in g and g['saved']==ref['saved'] and len(g['selected'])==ref['count'])
        print('%-12s seed%d %6.2fs got=%s ref=%s %s' % (style, seed, dt, json.dumps(g)[:90], ref, 'OK' if ok else '*** BAD'))
